  bennyFullH: 0.99 * KH0, pxW, coinEl, getS: () => st.s, getCoins: () => coinCount, render: () => renderer.render(scene, camera) });
const toSLH = (P) => { let bi = 0, bd = 1e9; for (let i = 0; i < RP.length; i += 2) { const d = RP[i].distanceToSquared(P); if (d < bd) { bd = d; bi = i; } } const s = bi * RDS, F = frameAt(s); return [s, Math.max(-0.3, Math.min(0.3, P.clone().sub(at(s, new THREE.Vector3())).dot(F.r)))]; };
const LAYC = [];
for (const A of WD.areas) {
  // each area's own coin rule (as its own page): painted coins ahead of Benny's painted contact point, then runs; the area's own coin size
  const key = WD.cam_keys.find((k) => k.area === A.id), cd = A.kind === 'kit' ? 2 * (A.LAY.coin_radius ?? 0.11) : coinD;
  if (A.kind === 'kit') { const sRef = key.s - (A.LAY.benny.ahead ?? 0); const pc = A.paintedCoins.map(toSLH).filter((c) => c[0] > sRef + 0.6); pc.forEach((c) => LAYC.push([c[0], c[1], cd])); const last = pc.length ? Math.max(...pc.map((c) => c[0])) : A.s0 + 2;
    for (let s = last + 2.2, k = 0; s < A.s1 - 1.0; s += 1.15, k++) LAYC.push([s, [0, 0.25, 0.25, 0, -0.25, -0.25][k % 6], cd]); }
  else for (const c of A.coinLay) LAYC.push([c[0], c[1], cd]);
}
