while (coins.length < LAYC.length) { const c0 = coins[0]; const sp = new THREE.Sprite(c0.sp.material.clone()); sp.scale.copy(c0.sp.scale); sp.renderOrder = 10; scene.add(sp);
  coins.push({ s: 0, lat: 0, h: 0, sp, got: -1, p0: sp.position.clone(), n0: new THREE.Vector3(0, 1, 0), run: 0, kind: 'water' }); }
coins.forEach((c, i) => { const L = LAYC[i]; if (!L) { c.sp.visible = false; c.s = 1e9; c.got = 0; return; } const F = frameAt(L[0]); c.s = L[0]; c.lat = L[1]; c.h = 0; c.d = L[2] ?? coinD; c.kind = Math.abs(L[1]) >= 0.1 ? 'lane' : 'water';
  at(L[0], c.p0).addScaledVector(F.r, L[1]).addScaledVector(F.n, c.d * 0.5); c.n0.copy(F.n); c.sp.position.copy(c.p0); });
