  const Ft = A2.sub(B2).normalize(), Fn = new THREE.Vector3(); for (let k = -2; k <= 2; k++) Fn.add(frameAt(Math.min(RLEN, Math.max(0, s + 0.4 * k))).n); Fn.normalize();
  const t = sm(new THREE.Vector3(Ft.x, 0, Ft.z).normalize(), Ft), n = sm(UPV, Fn), r = new THREE.Vector3().crossVectors(t, n).normalize(); n.crossVectors(r, t).normalize();
  return out.makeBasis(r, n, t.clone().negate()); };
const KEYS = WD.cam_keys.map((k) => { const Mk = camFrame(k.s, new THREE.Matrix4()), Mi = Mk.clone().invert(), Pk = at(k.s, new THREE.Vector3());
  const Qc = k.quat ? new THREE.Quaternion(...k.quat) : new THREE.Quaternion().setFromEuler(new THREE.Euler(k.pitch, k.yaw, 0, 'YXZ'));   // v4: a tilted area's camera
