  const kS = dt > 0 && st.camInit ? 1 - Math.exp(-14 * dt) : 1; st.camInit = true;
  st.rigO = (st.rigO ?? oT.clone()).lerp(oT, kS); st.rigQ = (st.rigQ ?? qT.clone()).slerp(qT, kS);
