  { const A = areaOf(s), CA = A.kind === 'kit' ? A.LAY?.cam_axis : null, key = CA ? WD.cam_keys.find((k) => k.area === A.id) : null;
    if (key && A.M) { const w = sstep(A.s0, A.s0 + 3, s) * (1 - sstep(A.s1 - 3, A.s1, s));
      if (w > 0) { const ax = new THREE.Vector3(0, 0, -1).transformDirection(A.M), side = new THREE.Vector3(1, 0, 0).transformDirection(A.M);
