// r46: Benny's screen box INCLUDING the paddling shader (VERT_BODY: arm strokes, kicks, bob, pompom swing, squash) - the old box used the
// rest pose, so a stroking arm could leave the screen while the box said he was inside. Same maths as the GPU, every 3rd vertex.
const bDef = (() => { const ss = (a, b, x) => { const t = Math.min(1, Math.max(0, (x - a) / (b - a))); return t * t * (3 - 2 * t); };
  const rot = (r, ax, ay, az, ang) => { const c = Math.cos(ang), s = Math.sin(ang), d = ax * r[0] + ay * r[1] + az * r[2];
    const cx = ay * r[2] - az * r[1], cy = az * r[0] - ax * r[2], cz = ax * r[1] - ay * r[0]; r[0] = r[0] * c + cx * s + ax * d * (1 - c); r[1] = r[1] * c + cy * s + ay * d * (1 - c); r[2] = r[2] * c + cz * s + az * d * (1 - c); };
  const q = [0, 0, 0];
  return (x, y, z, out) => { const uT = U.uT.value, uSwim = U.uSwim.value, uArmA = U.uArmA.value, side = x >= 0 ? 1 : -1;
    const wa = ss(0.30, 0.37, Math.abs(x)) * (1 - ss(0.08, 0.16, Math.abs(y + 0.18))); const ph0 = uT * 7.5 + (side > 0 ? 0 : 3.14159), ph = ph0 - 0.28 * Math.sin(ph0);
    q[0] = x - side * 0.31; q[1] = y + 0.18; q[2] = z; rot(q, 0, 0, 1, -side * uSwim * wa * uArmA * Math.sin(ph)); rot(q, 0, 1, 0, side * uSwim * wa * 0.5 * Math.cos(ph));
    let px = q[0] + side * 0.31, py = q[1] - 0.18, pz = q[2];
    const kz = ss(0.06, 0.24, pz) * (1 - ss(-0.36, -0.2, py)) * ss(0.02, 0.1, Math.abs(px)) * (1 - ss(0.26, 0.34, Math.abs(px))), kk = U.uKickA.value * 0.045 * kz * Math.sin(U.uKick.value * 11 + (side > 0 ? 0 : 3.14159));
    py += 0.35 * kk; pz += kk; const sp = Math.sin(uT * 7.5); py += U.uBobA.value * sp * sp;
    const wp = ss(0.17, 0.27, py); q[0] = px; q[1] = py - 0.19; q[2] = pz - 0.05; rot(q, 1, 0, 0, U.uPom.value.x * wp); rot(q, 0, 0, 1, U.uPom.value.y * wp); px = q[0]; py = q[1] + 0.19; pz = q[2] + 0.05;
    const sq = 1 + 0.03 * uSwim * Math.sin(uT * 15); py = (py + 0.5) * sq - 0.5; px /= Math.sqrt(sq); pz /= Math.sqrt(sq); return out.set(px, py, pz); }; })();
window.bennyBox = (stride = 3) => { benny.updateMatrixWorld(true); const a = bmesh.geometry.attributes.position, v = new THREE.Vector3(); let x0 = 1e9, x1 = -1e9, y0 = 1e9, y1 = -1e9;
  for (let i = 0; i < a.count; i += stride) { bDef(a.getX(i), a.getY(i), a.getZ(i), v).applyMatrix4(bmesh.matrixWorld).project(camera); const x = (v.x + 1) / 2 * W, y = (1 - v.y) / 2 * H; x0 = Math.min(x0, x); x1 = Math.max(x1, x); y0 = Math.min(y0, y); y1 = Math.max(y1, y); }
  return { x0: +x0.toFixed(1), x1: +x1.toFixed(1), y0: +y0.toFixed(1), y1: +y1.toFixed(1) }; };

