// section areas: water in world coordinates around the painted river line (route texture), offset to the area's placement
const waterMatSec = (A) => new THREE.ShaderMaterial({ side: THREE.DoubleSide,
  uniforms: { uT: WT, uGlow: A.glow, uSharp: { value: new THREE.Vector2(SHARPX, 2.2) }, uLodBias: { value: 0 }, uBake: { value: null }, uBakeOn: { value: 0 }, uDen: { value: null },
