  vertexShader: WVERT,
  fragmentShader: `uniform float uT; uniform vec3 uGlow; uniform sampler2D uBake; uniform float uBakeOn; uniform sampler2D uDen; uniform vec2 uSharp; uniform float uLodBias;
    uniform sampler2D uRoute; uniform vec2 uRZ; uniform vec4 uRW; uniform vec3 uOff; varying vec2 vUv; varying vec3 vW;
    ${WATER_CORE}
    float rc(float z){ return texture2D(uRoute, vec2(clamp((z - uRZ.x) / (uRZ.y - uRZ.x), 0.0, 1.0), 0.5)).r; }
    void main(){ vec3 L = vW - uOff; float z = L.z, d = -z, kR = clamp((uRW.z - z) / (uRW.z - uRW.w), 0.0, 1.0), RW = mix(uRW.x, uRW.y, kR * kR * (3.0 - 2.0 * kR));
      float cs = (rc(z - 0.05) - rc(z + 0.05)) * 10.0; float uw = (L.x - rc(z)) / sqrt(1.0 + cs * cs); float u = uw / RW, tp = d + uT * 1.6;
      vec3 col = waterCol(u, uw, tp, 0.5, 0.92, 1.0, 1.0, RW);   // = tools/reflock/section.html
      float fo = smoothstep(RW * 0.98, RW * 1.02, abs(uw)); if (fo > 0.0) { float nn = nse(vec2(L.x * 9.0, d * 9.0)); col = mix(col, mix(c3(185.0, 178.0, 240.0), c3(250.0, 248.0, 255.0), smoothstep(0.3, 0.8, nn)), fo); }
      col = bakeMix(col, vUv, vW, uBake, uDen, uBakeOn, uSharp, uLodBias, uT);
      col = mix(col, vec3(0.95, 1.0, 1.0), uGlow.z * pow(smoothstep(uGlow.x, uGlow.y, vW.z), 1.6)); gl_FragColor = vec4(col, 1.0); }` });

// ---------------- pre-baked approved pixels of an area (the bake was done once offline, same code as the area's own page) ----------------
const loadBake = async (A, meshes) => {
  const MANI = await fetch(A.dir + 'baked/manifest.json').then((r) => (r.ok ? r.json() : null)).catch(() => null); if (!MANI || GRAY) return MANI;
  const cache = {}; const ld = (f, den) => (cache[f] ??= tl.loadAsync(A.dir + 'baked/' + f).then((t) => { t.colorSpace = THREE.NoColorSpace; if (den) { t.generateMipmaps = false; t.minFilter = t.magFilter = THREE.LinearFilter; } else { t.anisotropy = 8; } return t; }));
  await Promise.all(meshes.filter((o) => MANI.meshes[o.name] && o.material.uniforms?.uBake).map(async (o) => { const e = MANI.meshes[o.name];
    o.material.uniforms.uBake.value = await ld(e.bake); o.material.uniforms.uDen.value = await ld(e.den, true); o.material.uniforms.uBakeOn.value = 1; }));
  return MANI; };

